export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const {
    Group,
    Mesh,
    BoxGeometry,
    CircleGeometry,
    DirectionalLight,
    Box3,
    Vector3,
    Color,
  } = THREE;
  const {
    MeshPhysicalNodeMaterial,
    MeshStandardNodeMaterial,
    MeshBasicNodeMaterial,
  } = await0(); // placeholder, replaced below

  return buildNode(config, ctx);
