// separated builder to keep top-level synchronous & clean
function buildNode(config, ctx) {
  const { THREE } = ctx;
  const {
    Group,
    Mesh,
    BoxGeometry,
    CircleGeometry,
    DirectionalLight,
    Box3,
    Vector3,
  } = THREE;

  const colors = config.intent?.visualSpec?.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10',
  };

  const root = new Group();
  root.name = 'hub-features-card';
  root.userData.handlers = {};
  root.userData.cleanup = () => {};

  const cleanupFns = [];

  // --- card panel (subject frame) -------------------------------------
  const CARD_W = 1.8;
  const CARD_H = 1.5;
  const CARD_D = 0.08;

  const panelGeo = new BoxGeometry(CARD_W, CARD_H, CARD_D);
  const panelMat = new MeshPhysicalNodeMaterialFrom(ctx, {
    color: colors.ink,
    roughness: 0.55,
    metalness: 0.4,
    clearcoat: 0.2,
    clearcoatRoughness: 0.4,
  });
  const panel = new Mesh(panelGeo, panelMat);
  panel.position.set(0, 0.12, 0);
  root.add(panel);

  // --- caption strip ----------------------------------------------------
  const STRIP_H = 0.32;
  const stripGeo = new BoxGeometry(CARD_W - 0.06, STRIP_H, CARD_D + 0.01);
  const stripMat = new MeshStandardNodeMaterialFrom(ctx, {
    color: colors.paper,
    roughness: 0.6,
    metalness: 0.1,
  });
  const strip = new Mesh(stripGeo, stripMat);
  strip.position.set(0, -CARD_H / 2 + STRIP_H / 2 + 0.09, CARD_D / 2 + 0.005);
  root.add(strip);

  // accent underline on the caption strip (thin sliver, <=10% of frame)
  const underlineGeo = new BoxGeometry(CARD_W - 0.06, 0.02, CARD_D + 0.02);
  const underlineMat = new MeshStandardNodeMaterialFrom(ctx, {
    color: colors.accent,
    roughness: 0.5,
    metalness: 0.15,
    emissive: colors.accent,
    emissiveIntensity: 1.1,
  });
  const underline = new Mesh(underlineGeo, underlineMat);
  underline.position.set(0, strip.position.y - STRIP_H / 2 + 0.01, CARD_D / 2 + 0.006);
  root.add(underline);

  // --- contact shadow beneath the subject --------------------------------
  const shadowGeo = new CircleGeometry(0.85, 32);
  const shadowMat = new MeshBasicNodeMaterialFrom(ctx, {
    color: '#000000',
    transparent: true,
    opacity: 0.45,
  });
  const shadow = new Mesh(shadowGeo, shadowMat);
  shadow.rotation.x = -Math.PI / 2;
  shadow.position.set(0, -CARD_H / 2 - 0.35, 0.3);
  root.add(shadow);

  // --- local rim / accent light (node-local, capped) ---------------------
  const rimLight = new DirectionalLight(new THREE.Color(colors.accent), 0.8);
  rimLight.position.set(-1.2, 0.8, 1.4);
  root.add(rimLight);

  const keyLocal = new DirectionalLight(0xffffff, 0.5);
  keyLocal.position.set(1.0, 1.2, 1.6);
  root.add(keyLocal);

  // --- subject: gear mesh from GLB -----------------------------------
  const subjectSlot = new Group();
  subjectSlot.position.set(0, 0.18, CARD_D / 2 + 0.02);
  root.add(subjectSlot);

  if (config.meshUrl) {
    ctx.glbLoader.loadGLB(config.meshUrl).then((gltf) => {
      const mesh = gltf.scene;
      // fit into card area, keep original materials/textures
      const box = new Box3().setFromObject(mesh);
      const size = new Vector3();
      box.getSize(size);
      const maxDim = Math.max(size.x, size.y, size.z, 0.0001);
      const targetSize = Math.min(CARD_W, CARD_H) * 0.62;
      const scale = targetSize / maxDim;
      mesh.scale.setScalar(scale);

      const center = new Vector3();
      box.getCenter(center);
      mesh.position.sub(center.multiplyScalar(scale));

      subjectSlot.add(mesh);

      // gentle idle rotation (one slow transform, machined-metal showcase)
      const idleTl = gsap.to(mesh.rotation, {
        y: `+=${Math.PI * 2}`,
        duration: 22,
        repeat: -1,
        ease: 'none',
      });
      cleanupFns.push(() => idleTl.kill());
    }).catch(() => {});
  }

  // --- entrance: weighted-settle -----------------------------------------
  root.scale.setScalar(0.001);
  root.position.y += 0.0; // adapter applies scenePosition; animate local offset instead
  const entranceState = { y: 0.4, s: 0.96 };
  root.userData.__baseY = 0;

  const entranceTl = gsap.timeline();
  entranceTl.fromTo(
    root.scale,
    { x: 0.001, y: 0.001, z: 0.001 },
    { x: 1.04, y: 1.04, z: 1.04, duration: 0.55, ease: 'power3.out' }
  ).to(root.scale, { x: 1, y: 1, z: 1, duration: 0.9, ease: 'power4.out' });
  cleanupFns.push(() => entranceTl.kill());

  // --- cinematic primitives -------------------------------------------
  const primitiveResults = [];
  const primitivesCfg = config.cinematicPrimitives ?? [];
  for (const prim of primitivesCfg) {
    const fn = ctx.primitives?.[prim.name];
    if (typeof fn === 'function') {
      const target = prim.name === 'magnetic-cursor' ? root : root;
      const result = fn(target, prim.params ?? {});
      if (result) primitiveResults.push(result);
    }
  }
  cleanupFns.push(() => {
    for (const r of primitiveResults) {
      try { r.cleanup?.(); } catch (e) {}
    }
  });

  // --- interaction handlers ---------------------------------------------
  let hoverTl = null;

  root.userData.handlers.pointerover = () => {
    if (hoverTl) hoverTl.kill();
    hoverTl = gsap.timeline();
    hoverTl.to(root.position, {
      y: '+=0.15',
      duration: 0.3,
      ease: 'power2.out',
    });
    hoverTl.to(panel.rotation, {
      x: -0.05,
      duration: 0.3,
      ease: 'power2.out',
    }, 0);
  };

  root.userData.handlers.pointerout = () => {
    if (hoverTl) hoverTl.kill();
    hoverTl = gsap.timeline();
    hoverTl.to(root.position, {
      y: '-=0.15',
      duration: 0.3,
      ease: 'power2.out',
    });
    hoverTl.to(panel.rotation, {
      x: 0,
      duration: 0.3,
      ease: 'power2.out',
    }, 0);
  };

  root.userData.handlers.click = () => {
    gsap.timeline()
      .to(root.scale, { x: 0.97, y: 0.97, z: 0.97, duration: 0.12, ease: 'power2.out' })
      .to(root.scale, { x: 1, y: 1, z: 1, duration: 0.25, ease: 'back.out(2)' });
    ctx.emit?.('hub-features.select', { id: 'hub-features-card-0' });
  };
  cleanupFns.push(() => { if (hoverTl) hoverTl.kill(); });

  // --- cleanup -----------------------------------------------------------
  root.userData.cleanup = () => {
    for (const fn of cleanupFns) {
      try { fn(); } catch (e) {}
    }
    panelGeo.dispose();
    panelMat.dispose?.();
    stripGeo.dispose();
    stripMat.dispose?.();
    underlineGeo.dispose();
    underlineMat.dispose?.();
    shadowGeo.dispose();
    shadowMat.dispose?.();
    root.traverse((obj) => {
      if (obj.geometry && obj !== panel && obj !== strip && obj !== underline && obj !== shadow) {
        obj.geometry.dispose?.();
      }
      if (obj.material && obj !== panel && obj !== strip && obj !== underline && obj !== shadow) {
        const mats = Array.isArray(obj.material) ? obj.material : [obj.material];
        for (const m of mats) {
          m.map?.dispose?.();
          m.dispose?.();
        }
      }
    });
  };

  return root;
}

